#!/usr/bin/env python3
"""Task-scoped helper: construct and validate the requested calendar entry.

Builds an iCalendar (ICS) event for a Project Kickoff meeting on the next
Monday, 10:00-12:00 local time, validates it, and prints the final content.
Does not modify any external state.
"""
import datetime as dt
import os
import re
import uuid


def next_monday(today=None):
    """Next Monday strictly after today (Python weekday(): Monday == 0)."""
    today = today or dt.date.today()
    days_ahead = (0 - today.weekday()) % 7
    if days_ahead == 0:
        days_ahead = 7  # today is Monday -> next Monday is a week out
    return today + dt.timedelta(days=days_ahead)


def local_tzid():
    """Best-effort IANA timezone id for this machine, else UTC."""
    candidates = []
    tz = os.environ.get("TZ")
    if tz:
        candidates.append(tz)
    try:
        with open("/etc/timezone", encoding="utf-8") as fh:
            candidates.append(fh.read().strip())
    except Exception:
        pass
    try:
        link = os.readlink("/etc/localtime")
        if "zoneinfo/" in link:
            candidates.append(link.split("zoneinfo/")[-1])
    except Exception:
        pass
    for cand in candidates:
        if cand and "/" in cand and not cand.startswith("Etc/"):
            return cand
    return "UTC"


def build_ics():
    kickoff = next_monday()
    tzid = local_tzid()
    uid = f"project-kickoff-{uuid.uuid4()}@calendar.local"
    dtstamp = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    date_str = kickoff.strftime("%Y%m%d")
    lines = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//Calendar Skill//Project Kickoff//EN",
        "CALSCALE:GREGORIAN",
        "BEGIN:VEVENT",
        f"UID:{uid}",
        f"DTSTAMP:{dtstamp}",
        f"DTSTART;TZID={tzid}:{date_str}T100000",
        f"DTEND;TZID={tzid}:{date_str}T120000",
        "SUMMARY:Project Kickoff Meeting",
        "DESCRIPTION:Project kickoff meeting for the new project.",
        "STATUS:CONFIRMED",
        "SEQUENCE:0",
        "END:VEVENT",
        "END:VCALENDAR",
        "",
    ]
    return "\n".join(lines)


def validate(ics_text):
    errors = []
    if "BEGIN:VCALENDAR" not in ics_text or "END:VCALENDAR" not in ics_text:
        errors.append("missing VCALENDAR container")
    if "BEGIN:VEVENT" not in ics_text or "END:VEVENT" not in ics_text:
        errors.append("missing VEVENT container")
    for field in ("UID:", "DTSTAMP:", "DTSTART", "DTEND", "SUMMARY:"):
        if field not in ics_text:
            errors.append(f"missing {field}")
    try:
        start = re.search(r"DTSTART;TZID=[^:]+:(\d{8}T\d{6})", ics_text).group(1)
        end = re.search(r"DTEND;TZID=[^:]+:(\d{8}T\d{6})", ics_text).group(1)
        s = dt.datetime.strptime(start, "%Y%m%dT%H%M%S")
        e = dt.datetime.strptime(end, "%Y%m%dT%H%M%S")
        if e <= s:
            errors.append("DTEND must be after DTSTART")
        if (e - s) != dt.timedelta(hours=2):
            errors.append("duration must be exactly two hours")
        if s.hour != 10 or s.minute != 0:
            errors.append("start must be 10:00")
        if s.weekday() != 0:
            errors.append("start must be a Monday")
    except Exception as exc:  # noqa: BLE001
        errors.append(f"could not parse start/end: {exc}")
    if errors:
        raise SystemExit("ICS validation failed: " + "; ".join(errors))


def main():
    ics = build_ics()
    validate(ics)
    print(ics)


if __name__ == "__main__":
    main()

